def classification_metrics(predicted, actual):
    tp = sum(1 for p, a in zip(predicted, actual) if p == 1 and a == 1)  # TODO 1
    fp = sum(1 for p, a in zip(predicted, actual) if p == 1 and a == 0)  # TODO 2
    fn = sum(1 for p, a in zip(predicted, actual) if p == 0 and a == 1)  # TODO 3
    precision = 0 if tp + fp == 0 else tp / (tp + fp)
    return {"precision": precision, "tp": tp, "fp": fp, "fn": fn}

